@dataclass(frozen=True)
class Task:
    title: str
    prompt: str
    hint: str
    cases: tuple
    level: str = "Beginner"


def task(title, prompt, hint, *cases, level="Beginner"):
    return Task(title, prompt, hint, cases, level)


