def employee_setup(rows):
    """Build trusted fixture data using SQL literal escaping for text only."""
    script = (
        "CREATE TABLE departments(id INTEGER PRIMARY KEY, name TEXT NOT NULL);\n"
        "INSERT INTO departments VALUES (1, 'Engineering'), (2, 'Support');\n"
        "CREATE TABLE employees(id INTEGER PRIMARY KEY, name TEXT NOT NULL, "
        "department_id INTEGER REFERENCES departments(id), salary INTEGER NOT NULL);\n"
    )
    for employee_id, name, department_id, salary in rows:
        safe_name = name.replace("'", "''")
        department = "NULL" if department_id is None else str(department_id)
        script += f"INSERT INTO employees VALUES ({employee_id}, '{safe_name}', {department}, {salary});\n"
    return script


FIXTURES = (
    employee_setup([(1, "Ada", 1, 80), (2, "Lin", 2, 50), (3, "Mo", 1, 90)]),
    employee_setup([]),
    employee_setup([(4, "Jo", None, 50), (5, "Bob", 2, 50), (6, "Eve", 2, 60)]),
)


