def exercises(topic, lesson):
    """Return runnable, deterministic practice fixtures for one topic."""
    topic_id = topic["id"]
    if topic_id in SQL_TASKS:
        spec = SQL_TASKS[topic_id]
        cases = [
            {"input": script, "expected": rows, "label": label}
            for script, rows, label in zip(FIXTURES, spec.expected, ("Sample directory", "Empty directory", "Missing department and tied salaries"))
        ]
        return [{
            "id": f"{topic_id}-practice", "title": spec.title, "difficulty": spec.level,
            "language": "sql", "prompt": spec.prompt, "hint": spec.hint, "setup": FIXTURES[0],
            "starter": "-- Write your SQL below. Explore the sample table first.\nSELECT * FROM employees ORDER BY id;\n",
            "sampleInput": cases[0]["input"], "sampleOutput": cases[0]["expected"], "tests": cases,
        }]
    specs = STRING_TASKS if topic_id == "strings" else {"practice": PYTHON[topic_id]}
    results = []
    for key, spec in specs.items():
        cases = [
            {"input": value, "expected": expected, "label": "Sample case" if i == 0 else f"Boundary check {i}"}
            for i, (value, expected) in enumerate(spec.cases)
        ]
        results.append({
            "id": f"{topic_id}-{key}", "title": spec.title, "difficulty": spec.level,
            "language": "python", "prompt": spec.prompt, "hint": spec.hint,
            "starter": "def solve(value):\n    # Write your solution here.\n    return None\n",
            "sampleInput": cases[0]["input"], "sampleOutput": cases[0]["expected"], "tests": cases,
        })
    return results


