def _choice(text, concept, correct, wrong, explanation, hint):
    options = [correct, *wrong]
    Random(text).shuffle(options)
    return dict(type="choice", text=text, concept=concept, options=options,
                answer=correct, explanation=explanation, hint=hint)


def _response(kind, text, concept, answer, explanation, hint):
    result = dict(type=kind, text=text, concept=concept, explanation=explanation, hint=hint)
    if kind == "output":
        result["answer"] = answer
    else:
        result["rubric"] = answer
    return result


def _coding(exercise, concept):
    return dict(type="coding", text=exercise["prompt"], exerciseId=exercise["id"],
                concept=concept, explanation=f"Check your implementation against the sample and boundary cases for {exercise['title']}.",
                hint=exercise["hint"])


def _strings_questions(level, exercise_set):
    if level == "Beginner":
        return [
            _choice("Which expression creates the text It's ready without a syntax error?", "String declaration",
                    '"It\'s ready"', ["'It's ready'", "It's ready"], "Double quotes can enclose an unescaped apostrophe.", "Compare the opening and closing delimiters."),
            _response("output", "What is printed?\n\nword = 'Python'\nprint(word[1:4])", "String slicing",
                      "yth", "Index 1 is y. The stop at index 4 is exclusive.", "Number the characters starting from zero."),
            _response("short", "Why does word[0] = 'J' fail for a Python string, and how can you obtain the changed text?", "Immutability",
                      [["immutable","cannot change","can't change","cannot modify","can't modify","cannot assign"],["new string","new value","concaten","rebind","slice","replace"]],
                      "String objects are immutable. Create a new value, for example 'J' + word[1:], and bind the name to it.", "Think about changing an object versus assigning a different value to a name."),
            _response("scenario", "A form receives '  Ada  ' and 'ADA'. Which two string operations would let it compare those names while ignoring surrounding spaces and case?", "String methods",
                      [["strip","trim"],["casefold","lower","lowercase"]],
                      "Strip both inputs, then compare their casefolded (or lowercased for this ASCII example) values.", "Handle the spacing and the letter case separately."),
            _coding(exercise_set[0], "Reversing text"),
        ]
    if level == "Intermediate":
        return [
            _choice("What is the difference between 'a  b'.split() and 'a  b'.split(' ')?", "Splitting and joining",
                    "The explicit separator produces an empty middle field", ["Both calls remove all empty fields", "The first call splits into individual letters"],
                    "Without an explicit separator, split() groups consecutive whitespace. Splitting on one literal space preserves empty fields between delimiters.", "Compare one run of whitespace with two literal separators."),
            _response("output", "What is printed?\n\ntext = 'interview'\nprint(text[-2:1:-2])", "String slicing",
                      "ev e".replace(" ", ""), "The visited indices are 7, 5 and 3, giving e, v and e.", "Write the indices in descending steps of two. The stop index is excluded."),
            _response("short", "How do split and join differ when converting a sentence to tokens and back into a normalized sentence?", "Splitting and joining",
                      [["list","tokens","pieces","words"],["separator","delimiter","between","single space"]], "split() produces a list of tokens. The separator before .join(...) is inserted between the tokens.", "Consider the return type of each operation."),
            _response("scenario", "A username comparison treats Straße and STRASSE as different after lower(). Why, and which Python operation handles this case?", "Unicode comparison",
                      [["casefold"],["ß","ss","unicode","sharp s","german"]], "Unicode casefolding maps the German sharp s to ss for caseless comparison. lower() does not perform that mapping.", "Some Unicode case comparisons involve a change in length."),
            _coding(exercise_set[1], "Palindrome normalization"),
        ]
    return [
        _choice("Which statement about len(s) in Python is accurate for arbitrary Unicode strings?", "Unicode representation",
                "It counts Unicode code points, which can differ from displayed characters", ["It always counts UTF-8 bytes", "It always counts user-perceived characters"],
                "One grapheme cluster may contain a base character and combining marks or a joined emoji sequence.", "A character can be drawn using more than one code point."),
        _response("output", "What is printed?\n\na = 'é'\nb = 'e' + '\\u0301'\nprint(a == b, len(b))", "Unicode normalization", "False 2",
                  "Python compares the sequences of code points. The second string contains e and a separate combining mark.", "Consider whether visually equivalent sequences must be identical."),
        _response("short", "Describe a linear-time algorithm for finding the first character occurring exactly once. Explain how it preserves input order.", "Frequency counting",
                  [["count","frequency","dictionary","counter"],["second","again","original order","original string","rescan"]], "Count characters once, then scan the original text for the first count of one.", "Separate measuring frequency from choosing which character comes first."),
        _response("scenario", "A system receives canonically equivalent accented names from different keyboards. How would you compare them without replacing the original spellings stored for display?", "Unicode normalization",
                  [["normaliz","nfc","nfd"],["original","separate","copy","comparison key","display"]], "Build normalized comparison keys (for example with unicodedata.normalize('NFC', text)) and retain original text for display.", "Distinguish the search key from the text a user entered."),
        _coding(exercise_set[3], "First unique character"),
    ]


def questions(topic, lesson, level="Beginner"):
    """Produce five topic-specific questions; grade keys stay on the server."""
    level = (level or "Beginner").title()
    if level not in {"Beginner", "Intermediate", "Advanced"}:
        raise ValueError("Unknown interview level")
    topic_id = topic["id"]
    exercise_set = exercises(topic, lesson)
    if topic_id == "strings":
        items = _strings_questions(level, exercise_set)
    else:
        item = CARDS[topic_id]
        task_item = exercise_set[0]
        concept = topic["concepts"][0] if topic.get("concepts") else topic["title"]
        short_text, group1, group2 = SHORT[topic_id]
        rubric = [group1.split("/"), group2.split("/")]
        # The output item uses a deterministic boundary fixture. Different
        # levels select different inputs independently from the coding editor.
        tests = task_item["tests"]
        index = {"Beginner": 1, "Intermediate": 2, "Advanced": len(tests)-1}[level]
        case = tests[min(index, len(tests)-1)]
        predicted = json.dumps(case["expected"], ensure_ascii=False, separators=(",", ":"))
        input_text = case["input"] if task_item["language"] == "sql" else json.dumps(case["input"], ensure_ascii=False)
        output_stem = (f"{task_item['prompt']}\n\nGiven this input, predict the returned value as JSON."
                       f"\n\n{input_text}")
        scenario_stem = item.scenario
        scenario_rubric = [list(group) for group in item.rubric]
        if level == "Advanced":
            scenario_stem += " Describe a test or observable check that would verify the fix."
            scenario_rubric.append(["test","assert","check","verify","observ","compare","measure","inspect","confirm"])
        if level == "Beginner":
            scenario_stem += " A one- or two-sentence answer is enough."
        items = [
            _choice(item.question, item.concept, item.correct, item.distractors,
                    item.correct + ".", f"Think about the guarantee behind {item.concept.lower()}."),
            _response("output", output_stem, task_item["title"], predicted,
                      f"Applying the stated rule to this fixture yields {predicted}.",
                      "Trace this input step by step, including any boundary or missing values."),
            _response("short", short_text, concept, rubric,
                      f"Look for both ideas in your answer: {' / '.join(rubric[0])} and {' / '.join(rubric[1])}.",
                      "Explain both parts of the question in your own words."),
            _response("scenario", scenario_stem, item.concept, scenario_rubric,
                      item.remedy + (" Verify the behavior with a targeted test." if level == "Advanced" else ""),
                      "Identify the broken assumption, then describe a concrete change."),
            _coding(task_item, task_item["title"]),
        ]
    for result in items:
        result.update(id=f"{topic_id}-{level.lower()}-{result['type']}",
                      difficulty=level, source="Locally curated", updated="2026-11-10")
    return items
